请对以下 case 进行三维加权评分。

=== case_id ===
Case-11-fitness-002

=== 用户原始指令 (query.txt) ===
弄个健身卡，点一下能跳app，要能读天气

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个健身卡，点一下能跳app，要能读天气",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县或当前位置名称",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/figure_run.svg",
      "description": "跑步人物黑色线性图标，适合运动健身卡片的主识别图形，建议放在浅色或低强度背板上。"
    },
    {
      "src": "resources/base/media/partly_cloudy.png",
      "description": "云朵与太阳组合的彩色天气图标，适合展示当前天气或户外运动前的天气参考。"
    }
  ]
}

